fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    // Only need to compare the first half of the array with the mirrored second half.
    // Each mismatch requires exactly one change.
    (0..n / 2)
        .filter(|&i| arr[i] != arr[n - 1 - i])
        .count()
}

